func testOrdemProducaoItemToOneSetOpProdutoUsingPro(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrdemProducaoItem
	var b, c Produto

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, ordemProducaoItemDBTypes, false, strmangle.SetComplement(ordemProducaoItemPrimaryKeyColumns, ordemProducaoItemColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, produtoDBTypes, false, strmangle.SetComplement(produtoPrimaryKeyColumns, produtoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Produto{&b, &c} {
		err = a.SetPro(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Pro != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.ProOrdemProducaoItems[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if a.ProID != x.ProID {
			t.Error("foreign key was wrong value", a.ProID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.ProID))
		reflect.Indirect(reflect.ValueOf(&a.ProID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if a.ProID != x.ProID {
			t.Error("foreign key was wrong value", a.ProID, x.ProID)
		}
	}
}

